def assess_all(tags):
 by={t['sourceURI']:t for t in tags}
 if len(by)!=len(tags):raise ValueError('Duplicate source definitions')
 decisions=[assess(t,by) for t in sorted(tags,key=lambda t:t['sourceURI'])]
 extensions={}
 for d in decisions:
  if d.get('schemaStatus')=='controlled_value_proposal':extensions.setdefault(d['trait'],set()).add(d['value'])
 return decisions,{'status':'proposed_not_active','existingDefinitions':len(INDEX),'newDefinitions':NEW_DEFINITIONS,'controlledValues':{k:sorted(v) for k,v in sorted(extensions.items())},'factualApproval':False,'sourceAuthorization':False}
